import {Link, ProgressBar, Stack, Text} from '@primer/react'
import {AlertFillIcon} from '@primer/octicons-react'
import styles from './CopilotQuotaUsage.module.css'

export interface CopilotQuotaUsageProps {
  completionsPercentageUsed: number
  chatPercentageUsed: number
  anyQuotasExhausted: boolean
  hasError?: boolean
}

export function CopilotQuotaUsage({
  completionsPercentageUsed,
  chatPercentageUsed,
  anyQuotasExhausted,
  hasError,
}: CopilotQuotaUsageProps) {
  return (
    <Stack direction="vertical">
      <Stack direction="horizontal" align="stretch" data-testid="copilot-quota-usage">
        <FeatureQuotaBar
          featureName="Code completions"
          featureKey="code-completions"
          percentageUsed={completionsPercentageUsed}
          anyQuotasExhausted={anyQuotasExhausted}
          hasError={hasError}
        />
        <FeatureQuotaBar
          featureName="Chat messages"
          featureKey="chat-messages"
          percentageUsed={chatPercentageUsed}
          anyQuotasExhausted={anyQuotasExhausted}
          hasError={hasError}
        />
      </Stack>
      {hasError && (
        <Stack direction="horizontal" align="center" gap="none" justify="start" role="alert">
          <AlertFillIcon size={12} className="fgColor-attention mr-1" />
          <Text size="small" weight="semibold" className={styles.errorText}>
            There was a problem loading your Copilot usage.{' '}
            <Link
              className={styles.reloadLink}
              onClick={e => {
                e.preventDefault()
                window.location.reload()
              }}
            >
              Try again
            </Link>
          </Text>
        </Stack>
      )}
    </Stack>
  )
}

interface FeatureQuotaBarProps {
  featureName: string
  featureKey: string
  percentageUsed: number
  anyQuotasExhausted: boolean
  hasError?: boolean
}

function FeatureQuotaBar({
  featureName,
  featureKey,
  percentageUsed,
  anyQuotasExhausted,
  hasError,
}: FeatureQuotaBarProps) {
  const progressBarColor = anyQuotasExhausted ? 'var(--bgColor-attention-emphasis)' : 'var(--bgColor-success-emphasis)'

  return (
    <Stack.Item grow className={styles.feature} data-testid={`copilot-quota-${featureKey}`}>
      <Stack direction="horizontal" justify="space-between" className={styles.header}>
        <span>{featureName}</span>
        <span data-testid={`copilot-quota-value-${featureKey}`}>{hasError ? '--' : `${percentageUsed}%`}</span>
      </Stack>
      <ProgressBar
        progress={hasError ? 0 : percentageUsed}
        bg={progressBarColor}
        aria-label={`Copilot ${featureName.toLowerCase()} quota usage`}
        data-testid={`copilot-quota-bar-${featureKey}`}
      />
    </Stack.Item>
  )
}
